package main

import (
	"fmt"
	"sync"
)

func work(id int) error {
	if id == 1 {
		return fmt.Errorf("job %d failed", id)
	}
	return nil
}

func main() {
	var wg sync.WaitGroup
	for i := 0; i < 3; i++ {
		wg.Add(1)
		go func() {
			if err := work(i); err != nil {
				fmt.Println(err)
				return
			}
			defer wg.Done()
		}()
	}
	wg.Wait()
	fmt.Println("all jobs finished")
}

func handler(w http.ResponseWriter, r *http.Request) {
	ctx := context.WithoutCancel(r.Context())
	go publish(ctx, "order.created")
	fmt.Fprintln(w, "ok")
}

func publish(ctx context.Context, topic string) error {
	select {
	case <-brokerReply(topic): // a broker that sometimes never answers
		return nil
	case <-ctx.Done():
		return ctx.Err()
	}
}
